import fs from 'node:fs';
import path from 'node:path';
import { drawnIcon, parseSvgIcon, type IconShape } from '../shared/addon-icons';
import { ADDON_ICONS, ICON_LIBRARY, manifestIconNames, type AddonManifest } from '../shared/addons';

/** Generated by scripts/build-icon-library.mjs. Only the main process reads it, and only for a manifest that names one, so a window never loads the whole library. */
const LIBRARY_FILE = path.join(__dirname, '../../assets/icon-library.json');
const LIBRARY_BOX = 24;

let library: Record<string, IconShape[]> | undefined;

function libraryIcon(name: string): string | undefined {
  library ??= JSON.parse(fs.readFileSync(LIBRARY_FILE, 'utf8')) as Record<string, IconShape[]>;
  const shapes = Object.hasOwn(library, name) ? library[name] : undefined;
  return shapes && drawnIcon({ box: LIBRARY_BOX, fill: 'none', stroke: 'currentColor', shapes });
}

type Icons = Pick<AddonManifest, 'icons' | 'panesIcon' | 'tabs' | 'commands'>;

/** The library names the manifest uses, with the field that names each. */
function libraryNames(m: Icons): { name: string; where: string }[] {
  const own = Object.entries(m.icons)
    .filter(([, value]) => value.startsWith(ICON_LIBRARY))
    .map(([name, value]) => ({ name: value, where: `icons: "${name}"` }));
  return [...own, ...manifestIconNames(m).filter((n) => n.name.startsWith(ICON_LIBRARY))];
}

/** A library icon the manifest names that doesn't exist; readAddonManifest checked the rest. */
export function addonIconError(m: Icons): string | undefined {
  const wrong = libraryNames(m).find((n) => !libraryIcon(n.name.slice(ICON_LIBRARY.length)));
  return wrong && `${wrong.where} names an icon the library doesn't have: "${wrong.name}"`;
}

const drawnCache = new WeakMap<Icons, Record<string, string>>();

/** The manifest's own and library icon names, as a surface draws them (addonIconKey). */
export function addonIcons(m: Icons): Record<string, string> {
  const cached = drawnCache.get(m);
  if (cached) return cached;
  const out: Record<string, string> = {};
  for (const [name, value] of Object.entries(m.icons)) {
    if ((ADDON_ICONS as readonly string[]).includes(name)) continue;
    if (value.startsWith(ICON_LIBRARY)) {
      const drawn = libraryIcon(value.slice(ICON_LIBRARY.length));
      if (drawn) out[name] = drawn;
      continue;
    }
    const svg = parseSvgIcon(value);
    if (svg.ok) out[name] = drawnIcon(svg.drawing);
  }
  for (const { name } of libraryNames(m)) {
    const drawn = libraryIcon(name.slice(ICON_LIBRARY.length));
    if (drawn) out[name] = drawn;
  }
  drawnCache.set(m, out);
  return out;
}
